      lore:'늑대인간, 호랑이인간, 독수리인간 등 다양한 수인 부족이 함께 사는 마을. 종족별로 독립된 문화를 가지지만 "무리의 규칙"이 모두를 묶는다. 상공회의소의 증기 개발이 숲을 위협하면서 부족들 사이에 긴장이 높아지고 있다.',
