      desc:'아이스크라운 왕국의 지도에는 표시되지 않는 곳 — 빙결 요새 글레이샤 너머, 인간도 얼음 거인족도 발 들이지 않는 황무지에 오크 부족들이 숨어 산다.',
      lore:'오크는 왕국에도, 요툰(얼음 거인족)에도 속하지 않는다. 건국전쟁 당시 왕국에 패해 변경으로 쫓겨난 후손들이 수백 년간 인간들 눈을 피해 살아왔다. "말하는 자(현자)"의 조언 없이는 어떤 전쟁족장도 결정을 내리지 않는 엄격한 부족 체계가 그들을 지금까지 지켜냈다. 왕국 사람들은 이들이 멸종했거나 흩어졌다고 믿는다 — 그게 오크들이 원하는 바이기도 하다.',
