      triggerKeywords:['그롬바르','은둔부족','오크 부족','전쟁족장','숨겨진 부족'],
      discoveryHint: '이 장소는 일반적인 탐험으로는 발견되지 않는다 — 오크와의 우호적 접촉(전투에서 살려주거나, 길을 잃은 오크를 도와주는 등)이나 빙결 요새 변경 깊숙이 들어가는 모험을 통해서만 그 존재가 드러나야 한다. 발견되는 순간 GS에 "hidden_location_found":"loc_orc_warcamp" 를 출력하라.',
