      desc:'왕도 아이런홀 인근, 평범한 협곡 마을로만 보이는 저택가. 낮에는 인간 가문이 사는 것처럼 보이지만, 밤이 되면 전혀 다른 사회가 깨어난다.',
      lore:'뱀파이어는 인간 왕국 어디에도 공식적인 영토를 갖지 못한다. 들키는 순간 "뱀파이어 사냥꾼단"이 조직되기 때문이다. 그래서 이들은 위장한다 — 가짜 인간 가문의 이름으로, 평범한 협곡 마을의 모습으로. 시간을 먹는 존재인 그들에게는 누구의 피를 마셨는가, 누가 그 이름을 두려워하는가가 곧 역사이자 신분이다.',
      rumors:['이 저택가의 한 가문이 수백 년째 똑같은 외모로 목격된다는 소문(아무도 입 밖에 내지 않는다)','일부 귀족이 한밤중에 이 마을을 드나든다는 의혹','밤마다 저택가에서 인간 손님을 초대해 연회를 연다는 이야기 — 돌아오지 않는 손님도 있다는 뒷이야기'],
