      desc:'아이스크라운 왕국의 지도에도, 어떤 왕국의 공식 영토에도 속하지 않는 황무지 — 생명 에너지가 고갈되어 불사 생명체들이 자연스럽게 모여드는 곳.',
      lore:'언데드는 세계로부터 시간을 빌린 존재다. 강렬한 집착이든 빼앗긴 삶이든, 죽었어야 할 순간에 죽지 못한 자들이 이 황무지로 모여든다. 강령술사 모르티머가 이끄는 "불사 군단"이 이곳을 지배하며, 암흑 결사의 전위 무력으로 활동한다. 살아있는 인간들의 법은 언데드를 "비시민"으로 규정하며 발견 즉시 처치를 명한다 — 그래서 그들은 인간의 법이 닿지 않는 이 땅에서만 평화를 얻는다.',
